const BRAND_SUBTITLES={"tr": "ÖZEL ŞARAP LİSTESİ", "en": "EXCLUSIVE WINE LIST", "de": "EXKLUSIVE WEINKARTE", "ru": "ЭКСКЛЮЗИВНАЯ ВИННАЯ КАРТА", "es": "CARTA EXCLUSIVA DE VINOS", "fr": "CARTE DES VINS EXCLUSIVE", "ro": "LISTĂ EXCLUSIVĂ DE VINURI", "sk": "EXKLUZÍVNY VÍNNY LÍSTOK", "uk": "ЕКСКЛЮЗИВНА ВИННА КАРТА", "it": "CARTA DEI VINI ESCLUSIVA", "fil": "EKSKLUSIBONG LISTAHAN NG ALAK", "zh": "精选酒单", "ja": "特選ワインリスト", "hi": "विशेष वाइन सूची", "ko": "프리미엄 와인 리스트", "nl-BE": "EXCLUSIEVE WIJNKAART", "pl": "EKSKLUZYWNA KARTA WIN"};Object.entries(BRAND_SUBTITLES).forEach(([lang,text])=>I18N[lang].exclusiveWineList=text);
let wines=[],filtered=[],selected=null,visible=32;const state={lang:'tr',category:'all',body:'all',country:'',query:'',restaurant:'',meal:''};try{const saved=localStorage.getItem('papillon-language');if(I18N[saved])state.lang=saved}catch{}
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const t=k=>I18N[state.lang]?.[k]??I18N.en[k]??I18N.tr[k]??'';const price=n=>new Intl.NumberFormat(state.lang,{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);const number=n=>new Intl.NumberFormat(state.lang).format(n);const score=w=>new Intl.NumberFormat(state.lang,{minimumFractionDigits:1,maximumFractionDigits:1}).format(Number(w.rating.score));
function ratingLabel(w){return w.rating.status==='found'?score(w)+' / 5':t(w.rating.status==='insufficient'?'insufficient':w.rating.status==='identity_unconfirmed'?'identity':'unverified')}
function translateUI(){document.documentElement.lang=state.lang;document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(key==='title')el.innerHTML=t(key).replace(/<br\s*\/?\s*>/gi,' ');else el.textContent=t(key)});$('language').value=state.lang;$('detailLanguage').value=state.lang;$('language').setAttribute('aria-label',t('language'));$('detailLanguage').setAttribute('aria-label',t('language'));$('search').placeholder=t('search');$('search').setAttribute('aria-label',t('search'));$('close').setAttribute('aria-label',t('close'));$('previous').textContent='← '+t('previous');$('next').textContent=t('next')+' →';$('categories').setAttribute('aria-label',t('catalog'));$('grid').setAttribute('aria-label',t('catalog'));$('welcomeVideo').setAttribute('aria-label',t('filmLabel'))}
function renderCategories(){$('categories').innerHTML=['all','sparkling','white','rose','red','sweet'].map(cat=>`<button class="category-button ${state.category===cat?'active':''}" data-category="${cat}" aria-pressed="${state.category===cat}">${esc(t(cat))}</button>`).join('');$('categories').querySelectorAll('button').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;state.country='';visible=32;renderAll()})}

function renderBodies(){const choices=[['all','bodyAll'],['light','body_light'],['light_medium','bodyRange_light_medium'],['medium','body_medium'],['medium_full','bodyRange_medium_full'],['full','body_full']];$('bodies').setAttribute('aria-label',t('bodyFilterTitle'));$('bodies').innerHTML=choices.map(([body,key])=>`<button class="category-button body-button ${state.body===body?'active':''}" data-body="${body}" aria-pressed="${state.body===body}">${esc(t(key))}</button>`).join('');$('bodies').querySelectorAll('button').forEach(b=>b.onclick=()=>{state.body=b.dataset.body;visible=32;renderAll()})}
function renderCountries(){const available=CatalogCore.countries(wines,state.category,state.body);if(!available.includes(state.country))state.country='';const localized=available.map(key=>({key,label:wines.find(w=>w.country_en===key).local[state.lang].country})).sort((a,b)=>a.label.localeCompare(b.label,state.lang));$('country').innerHTML=`<option value="">${esc(t('allCountries'))}</option>`+localized.map(c=>`<option value="${esc(c.key)}">${esc(c.label)}</option>`).join('');$('country').value=state.country}
function renderGrid(){filtered=CatalogCore.filter(wines,state).filter(w=>!state.meal||window.PAPILLON_MEALS.find(m=>m.id===state.meal)?.wines.includes(w.id));$('resultCount').textContent=number(filtered.length)+' '+t('shown');$('grid').innerHTML=filtered.slice(0,visible).map(w=>{const a=w.local[state.lang]||w.local.en;return `<article class="wine-card"><div class="bottle-area"><div class="price-tag">${esc(price(w.menu_price_eur))}<small>${esc(t('menuPrice'))}</small></div><img src="${w.image}" alt="${esc(w.name)}" loading="lazy" width="292" height="527"></div><div class="wine-info"><div class="card-category">${esc(a.beverage_display||t(w.category))}</div><h3>${esc(w.name)}</h3><p class="origin">${esc(a.country)} · ${esc(a.region_display)}</p><div class="card-facts"><span>${esc(w.year)}</span><span class="rating ${w.rating.status==='found'?'':'missing'}">${w.rating.status==='found'?'★ ':''}${esc(ratingLabel(w))}</span></div><button class="view-button" data-wine="${w.id}">${esc(t('view'))} ↗</button></div></article>`}).join('');$('grid').querySelectorAll('[data-wine]').forEach(b=>b.onclick=()=>openWine(Number(b.dataset.wine)));$('more').hidden=visible>=filtered.length;$('empty').hidden=filtered.length!==0;if(selected!==null&&$('detail').open)renderDetail()}
function renderAll(){renderMealFilters();translateUI();renderCategories();renderBodies();renderCountries();renderGrid()}
function setLanguage(lang){if(!I18N[lang])return;state.lang=lang;try{localStorage.setItem('papillon-language',lang)}catch{}renderAll()}
function openWine(id){selected=id;renderDetail();$('detail').showModal();$('close').focus()}
function bodyLabel(w){return CatalogCore.bodyKeys(w).map(key=>t(({light:'body_light',light_medium:'bodyRange_light_medium',medium:'body_medium',medium_full:'bodyRange_medium_full',full:'body_full',unspecified:'body_unspecified'})[key])).join(' / ')}
function renderDetail(){const w=wines.find(w=>w.id===selected);if(!w)return;const a=w.local[state.lang]||w.local.en;const alcohol=a.alcohol?(w.education?a.alcohol:(a.alcohol.includes('(')?a.alcohol:a.alcohol+' ('+t('generalAlcohol')+')')):'';const info=(label,value,note='',wide=false)=>`<div class="${wide?'span2':''}"><span class="info-label">${esc(label)}</span><p class="info-value">${esc(value)}</p>${note?`<p class="info-note">${esc(note)}</p>`:''}</div>`;const ratingNote=w.rating.status==='found'?`${t('overall')} ${w.rating.count?number(Number(w.rating.count))+' '+t('ratings')+'. ':''}${t('checked')}`:t('checked');$('detailBody').innerHTML=`<div class="detail-layout"><aside class="detail-aside"><div class="detail-bottle"><div class="price-tag">${esc(price(w.menu_price_eur))}<small>${esc(t('menuPrice'))}</small></div><img src="${w.image}" alt="${esc(w.name)}" width="292" height="527"></div>${a.image_note?`<p class="map-caption">${esc(a.image_note)}</p>`:""}<div><div class="map-block"><img src="${w.map}" alt="${esc(a.country+' / '+a.region_display)}"><span class="compass">${esc(t('north'))}</span><span class="map-label">${esc(a.region_display)}</span></div><p class="map-caption">${esc(t('map'))}</p></div></aside><div class="detail-content"><span class="detail-category">${esc(a.beverage_display||t(w.category))}</span><h2>${esc(w.name)}</h2><div class="detail-origin">${esc(a.country)} / ${esc(a.region_display)}</div><div class="details-grid">${info(t('vintage'),w.year,w.year==='N.V.'?t('nonVintage'):'')}${info(t('vivino'),ratingLabel(w),ratingNote)}${info(t('grapes'),w.blend,a.blend_note,true)}<div class="span2"><span class="info-label">${esc(t('character'))}</span>${PapillonSensory.html(w,state.lang,bodyLabel(w))}<p class="character">${esc(PapillonSensory.character(w,state.lang))}</p></div>${info(t('service'),w.temperature+' / '+a.glass,a.service_note,true)}${alcohol?info(t('alcohol'),alcohol,'',true):''}</div><section class="detail-section"><h3>${esc(t('food'))}</h3><dl class="pairing-list">${a.food_groups.map(([head,body])=>`<div><dt>${esc(head)}</dt><dd>${esc(body)}</dd></div>`).join('')}</dl>${a.food_group_focus?`<p class="extra-note">${esc(a.food_group_focus)}</p>`:''}<p class="example-note"><b>${esc(a.examples_label||t('examples'))}:</b> ${esc(a.food_display)}</p></section><section class="detail-section"><h3>${esc(t('cheese'))}</h3><p class="info-value"><b>${esc(a.cheese)}</b></p><p class="cheese-reason">${esc(a.cheese_reason)}</p></section></div></div>`;let i=filtered.findIndex(x=>x.id===selected);if(i<0)i=wines.findIndex(x=>x.id===selected);const list=filtered.some(x=>x.id===selected)?filtered:wines;$('detailPosition').textContent=(i+1)+' / '+list.length;$('previous').disabled=i<=0;$('next').disabled=i>=list.length-1;$('detailLanguage').value=state.lang;$('previous').onclick=()=>navigate(-1);$('next').onclick=()=>navigate(1)}
function navigate(delta){const list=filtered.some(x=>x.id===selected)?filtered:wines;const i=list.findIndex(x=>x.id===selected);const target=list[i+delta];if(target){selected=target.id;renderDetail();$('detail').scrollTop=0}}
$('language').onchange=e=>setLanguage(e.target.value);$('detailLanguage').onchange=e=>setLanguage(e.target.value);$('search').oninput=e=>{state.query=e.target.value;visible=32;renderGrid()};$('country').onchange=e=>{state.country=e.target.value;visible=32;renderGrid()};$('clear').onclick=()=>{state.category='all';state.body='all';state.country='';state.query='';state.restaurant='';state.meal='';visible=32;$('search').value='';renderAll()};$('more').onclick=()=>{visible+=32;renderGrid()};$('close').onclick=()=>$('detail').close();$('detail').onclick=e=>{if(e.target===$('detail')){const r=$('detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('detail').close()}};
translateUI();fetch((document.documentElement.dataset?.catalog||'wines.json')+'?v=20261019-original-bottles').then(r=>{if(!r.ok)throw Error('load');return r.json()}).then(data=>{wines=data;renderAll()}).catch(()=>{$('grid').textContent=t('error');$('more').hidden=true});

function renderMealFilters(){
 let box=document.getElementById('mealFilters');
 if(!box){box=document.createElement('div');box.id='mealFilters';box.className='body-filter';document.querySelector('.country-row').before(box)}
 const labels={tr:['Yemeğinize uygun şarap','Restoran seçin','Tüm restoranlar','Yemek seçin','Tüm yemekler'],en:['Wine with your meal','Restaurant','All restaurants','Dish','All dishes'],de:['Wein zum Gericht','Restaurant','Alle Restaurants','Gericht','Alle Gerichte'],ru:['Вино к блюду','Ресторан','Все рестораны','Блюдо','Все блюда']};
 const l=labels[state.lang]||labels.en;
 box.innerHTML=`<h3>${esc(l[0])}</h3><div class="country-row"><label for="mealRestaurant">${esc(l[1])}</label><select id="mealRestaurant"><option value="">${esc(l[2])}</option>${['İtalyan','Kanji','Balık'].map(r=>`<option ${state.restaurant===r?'selected':''}>${esc(r)}</option>`).join('')}</select><label for="mealDish">${esc(l[3])}</label><select id="mealDish"><option value="">${esc(l[4])}</option>${window.PAPILLON_MEALS.filter(m=>!state.restaurant||m.restaurant===state.restaurant).map(m=>`<option value="${m.id}" ${m.id===state.meal?'selected':''}>${esc(m.restaurant+' · '+m.name)}</option>`).join('')}</select></div><p id="mealReason" class="body-filter-note" aria-live="polite"></p>`;
 const m=window.PAPILLON_MEALS.find(x=>x.id===state.meal);$('mealReason').textContent=m?m.reason:'';
 $('mealRestaurant').onchange=e=>{state.restaurant=e.target.value;state.meal='';visible=32;renderAll()};
 $('mealDish').onchange=e=>{state.meal=e.target.value;visible=32;renderAll()};
}
